using System.Reflection;
using System.Reflection.Metadata;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;

namespace PaymentAuthorization.IntegrationTest.Architecture;

public class LayerDependencyTests
{
    // Business code may only use the language core: no I/O, network, serialization or persistence namespaces.
    private static readonly string[] CoreNamespaces =
    [
        "System",
        "System.Collections",
        "System.Collections.Generic",
        "System.Collections.Immutable",
        "System.Linq",
        "System.Threading",
        "System.Threading.Tasks",
        "System.Runtime.CompilerServices",
        "System.Diagnostics.CodeAnalysis",
    ];

    private const string DomainNamespace = "PaymentAuthorization.Domain";
    private const string ApplicationNamespace = "PaymentAuthorization.Application";

    [Fact]
    public void Domain_depends_only_on_Domain_and_the_language_core()
    {
        var violations = FindViolations(typeof(Money).Assembly, [DomainNamespace]);

        Assert.True(violations.Count == 0, "Violations: " + string.Join("; ", violations));
    }

    [Fact]
    public void Application_depends_only_on_Application_Domain_and_the_language_core()
    {
        var violations = FindViolations(typeof(AuthorizePayment).Assembly, [DomainNamespace, ApplicationNamespace]);

        Assert.True(violations.Count == 0, "Violations: " + string.Join("; ", violations));
    }

    private static List<string> FindViolations(Assembly assembly, string[] ownNamespaces)
    {
        using var stream = File.OpenRead(assembly.Location);
        using var pe = new System.Reflection.PortableExecutable.PEReader(stream);
        var reader = pe.GetMetadataReader();
        var allowed = CoreNamespaces.Concat(ownNamespaces).ToHashSet();
        var violations = new List<string>();

        foreach (var handle in reader.TypeReferences)
        {
            var reference = reader.GetTypeReference(handle);
            var ns = reader.GetString(reference.Namespace);
            if (allowed.Contains(ns)) continue;
            violations.Add($"{assembly.GetName().Name} uses {ns}.{reader.GetString(reference.Name)}");
        }

        return violations;
    }
}
EOF
cd ../.. && dotnet test tests/PaymentAuthorization.IntegrationTest --filter LayerDependency 2>&1 | tail -15

